// In-process lifecycle scenarios for #295. Every opaque value is generated by
// the existing synthetic fixture; no token is read from an environment or disk.
// The memory boundary models serial persistence only, not encryption, native
// lease exclusivity, process restart, device behavior or a real provider.

use crate::ai::{
    Cancellation, ConnectionSnapshot,
    host::{
        HostAuthority,
        lifecycle::{ConnectionFacts, StoredSession},
        transport::InferenceSession,
    },
};

struct StaleReadyFacts;
impl HostAuthority<()> for StaleReadyFacts {
    fn binding(&self, _: &()) -> Result<RegistrationBinding, AiError> {
        Ok(binding())
    }
    fn revalidate(&self, _: &(), captured: &RegistrationBinding) -> Result<(), AiError> {
        assert_eq!(captured, &binding());
        Ok(())
    }
}
impl ConnectionFacts<()> for StaleReadyFacts {
    fn observe<'a>(
        &'a self,
        _: &'a (),
        _: &'a RegistrationRecord,
        _: &'a str,
        _: &'a Cancellation,
    ) -> PortFuture<'a, ConnectionSnapshot> {
        Box::pin(async {
            // Deliberately stale ready metadata cannot override record state.
            let snapshot: ConnectionSnapshot = serde_json::from_value(serde_json::json!({
                "method": "sign-in-with-chatgpt", "permission": "granted",
                "eligibility": "eligible", "authorization": "connected",
                "account": {"accountId":"synthetic-account", "workspaceId":"synthetic-workspace", "label":"Synthetic account"},
                "paidUseAdmission": "verified-zero-paid-use", "usageSupported": false,
                "runtime": {"kind":"local", "route":"local-inference-companion", "qualification":"qualified", "availability":"ready", "checkedAt":"2026-10-25T00:00:00Z"}
            })).expect("synthetic ready observation");
            assert!(snapshot.can_infer());
            Ok(snapshot)
        })
    }
}

fn assert_held_session(storage: SyntheticBoundary) {
    let session = StoredSession {
        credentials: storage,
        observation: StaleReadyFacts,
        authority: StaleReadyFacts,
    };
    assert!(matches!(
        ready(session.acquire(&(), "synthetic-model", &Cancellation::default())),
        Err(AiError::ConnectionUnavailable)
    ));
}

#[derive(Clone, Copy)]
enum RefreshFailure {
    Transport,
    Rejected,
    InvalidGrant,
}

struct UnavailableProvider<'a> {
    storage: &'a SyntheticBoundary,
    failure: RefreshFailure,
    refreshes: AtomicUsize,
    revocations: AtomicUsize,
}
impl<'a> UnavailableProvider<'a> {
    fn new(storage: &'a SyntheticBoundary, failure: RefreshFailure) -> Self {
        Self {
            storage,
            failure,
            refreshes: AtomicUsize::new(0),
            revocations: AtomicUsize::new(0),
        }
    }
}
impl OAuthProviderPort for UnavailableProvider<'_> {
    fn exchange<'a>(
        &'a self,
        _: &'a RegistrationBinding,
        _: CodeExchange<'a>,
    ) -> PortFuture<'a, ProviderTokens> {
        Box::pin(async { panic!("lifecycle scenarios must not exchange a code") })
    }
    fn refresh<'a>(
        &'a self,
        scope: &'a RegistrationBinding,
        grant: RefreshGrant<'a>,
    ) -> PortFuture<'a, ProviderTokens> {
        Box::pin(async move {
            assert_eq!(scope, &binding());
            assert_eq!(grant.client_id, CLIENT);
            assert_eq!(grant.resource, OAUTH_RESOURCE);
            // The actual lifecycle must persist its invocation before handing
            // control to even this fake transport. Opaque values stay unread.
            let saved = self.storage.0.lock().expect("synthetic storage");
            assert_eq!(saved.state, LifecycleState::RefreshUnconfirmed);
            assert!(matches!(
                &saved.refresh_checkpoint,
                RefreshCheckpoint::InvocationUnconfirmed(captured) if captured == scope
            ));
            drop(saved);
            self.refreshes.fetch_add(1, Ordering::Relaxed);
            match self.failure {
                RefreshFailure::Transport => Err(AiError::ProviderUnavailable),
                RefreshFailure::Rejected | RefreshFailure::InvalidGrant => {
                    Ok(ProviderTokens::Rejected(ProviderDiagnostic {
                        http_status: Some(400),
                        code: Some(
                            match self.failure {
                                RefreshFailure::InvalidGrant => "invalid_grant",
                                _ => "synthetic_provider_rejection",
                            }
                            .into(),
                        ),
                        parameter: None,
                        request_id: None,
                    }))
                }
            }
        })
    }
    fn revoke<'a>(
        &'a self,
        scope: &'a RegistrationBinding,
        client: &'a str,
        _: &'a ProtectedValue,
    ) -> PortFuture<'a, ProviderRevocation> {
        Box::pin(async move {
            assert_eq!(scope, &binding());
            assert_eq!(client, CLIENT);
            let saved = self.storage.0.lock().expect("synthetic storage");
            assert_eq!(saved.state, LifecycleState::Disconnected);
            assert_eq!(saved.revocation, RevocationState::Unconfirmed);
            assert!(saved.pending_authorization.is_none());
            drop(saved);
            self.revocations.fetch_add(1, Ordering::Relaxed);
            Ok(ProviderRevocation::Unconfirmed(None))
        })
    }
}

fn connected_registration() -> RegistrationRecord {
    let mut record = empty_registration();
    record.issued_client_id = Some(CLIENT.into());
    record.identity = Some(VerifiedIdentity {
        subject: "synthetic-verified-subject".into(),
        name: None,
        email: None,
    });
    record.credentials = Some(saved_tokens(token_reply(true), Vec::new()));
    record.state = LifecycleState::Connected;
    record
}

#[test]
fn uncertain_refresh_keeps_checkpoint_and_never_resubmits() {
    for failure in [RefreshFailure::Transport, RefreshFailure::Rejected] {
        let storage = SyntheticBoundary(Mutex::new(connected_registration()));
        let provider = UnavailableProvider::new(&storage, failure);
        let lifecycle = OAuthLifecycle {
            security: &SyntheticSecurity,
            provider: &provider,
            credentials: &storage,
        };
        let receipt = ready(lifecycle.refresh(&(), &binding())).expect("synthetic refresh");
        assert_eq!(receipt.state, LifecycleState::RefreshUnconfirmed);
        assert_eq!(
            receipt.issue,
            Some(match failure {
                RefreshFailure::Transport => OAuthIssue::RefreshUnconfirmed,
                _ => OAuthIssue::ProviderRejected,
            })
        );
        // Reconstruct only the orchestration object over the same memory peer.
        // This checks state-driven refusal, not durable process recovery.
        let reopened = OAuthLifecycle {
            security: &SyntheticSecurity,
            provider: &provider,
            credentials: &storage,
        };
        let receipt = ready(reopened.refresh(&(), &binding())).expect("held refresh status");
        assert_eq!(receipt.state, LifecycleState::RefreshUnconfirmed);
        assert_eq!(receipt.issue, Some(OAuthIssue::RefreshUnconfirmed));
        assert_eq!(provider.refreshes.load(Ordering::Relaxed), 1);
        assert_eq!(provider.revocations.load(Ordering::Relaxed), 0);
        let saved = storage.0.lock().expect("synthetic storage");
        assert!(matches!(
            &saved.refresh_checkpoint,
            RefreshCheckpoint::InvocationUnconfirmed(captured) if captured == &binding()
        ));
        assert!(saved.credentials.is_some());
        assert_eq!(saved.state, LifecycleState::RefreshUnconfirmed);
        drop(saved);
        assert_held_session(storage);
    }
}

#[test]
fn invalid_grant_requires_explicit_reauthorization_without_refresh_replay() {
    let storage = SyntheticBoundary(Mutex::new(connected_registration()));
    let provider = UnavailableProvider::new(&storage, RefreshFailure::InvalidGrant);
    let lifecycle = OAuthLifecycle {
        security: &SyntheticSecurity,
        provider: &provider,
        credentials: &storage,
    };
    for _ in 0..2 {
        let receipt = ready(lifecycle.refresh(&(), &binding())).expect("reauthorization status");
        assert_eq!(receipt.state, LifecycleState::ReauthorizationRequired);
        assert_eq!(
            receipt.issue,
            Some(OAuthIssue::ExplicitReauthorizationRequired)
        );
    }
    assert_eq!(provider.refreshes.load(Ordering::Relaxed), 1);
    assert_eq!(provider.revocations.load(Ordering::Relaxed), 0);
    let saved = storage.0.lock().expect("synthetic storage");
    assert!(saved.credentials.is_none());
    assert!(matches!(saved.refresh_checkpoint, RefreshCheckpoint::None));
    assert_eq!(saved.issued_client_id.as_deref(), Some(CLIENT));
    assert_eq!(
        saved.identity.as_ref().unwrap().subject,
        "synthetic-verified-subject"
    );
    drop(saved);
    assert_held_session(storage);
}

#[test]
fn local_disconnect_does_not_claim_remote_revocation_or_restore_refresh() {
    let storage = SyntheticBoundary(Mutex::new(connected_registration()));
    let provider = UnavailableProvider::new(&storage, RefreshFailure::Transport);
    let lifecycle = OAuthLifecycle {
        security: &SyntheticSecurity,
        provider: &provider,
        credentials: &storage,
    };
    let receipt = ready(lifecycle.disconnect(&(), &binding())).expect("synthetic disconnect");
    assert_eq!(receipt.state, LifecycleState::Disconnected);
    assert_eq!(receipt.revocation, RevocationState::Unconfirmed);
    assert_eq!(provider.revocations.load(Ordering::Relaxed), 1);
    // A later refresh is a local held result, never a reconnect or revoke retry.
    let refresh = ready(lifecycle.refresh(&(), &binding())).expect("disconnected status");
    assert_eq!(refresh.state, LifecycleState::Disconnected);
    assert_eq!(
        refresh.issue,
        Some(OAuthIssue::ExplicitReauthorizationRequired)
    );
    assert_eq!(refresh.revocation, RevocationState::Unconfirmed);
    assert_eq!(provider.refreshes.load(Ordering::Relaxed), 0);
    assert_eq!(provider.revocations.load(Ordering::Relaxed), 1);
    let saved = storage.0.lock().expect("synthetic storage");
    assert_eq!(saved.state, LifecycleState::Disconnected);
    assert_eq!(saved.revocation, RevocationState::Unconfirmed);
    // Unconfirmed renewable material remains with the original owner for an
    // explicit recovery decision. Local stop is not a claim of token removal.
    assert!(saved.credentials.is_some());
    assert_eq!(saved.issued_client_id.as_deref(), Some(CLIENT));
    drop(saved);
    assert_held_session(storage);
}
